import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";

function IncomeCategory({ onNext }) {
  const [selectedIncome, setSelectedIncome] = useState("");
  const navigate = useNavigate();

  const handleSelect = (type) => {
    setSelectedIncome(type);
  };

  const handleContinue = () => {
    if (!selectedIncome) {
      alert("Please select an income category");
      return;
    }

    if (onNext) onNext(selectedIncome);
    navigate("/questionnaire");
  };

  return (
    <div className="income-container">
      <h1 className="income-title">Select Your Income Category</h1>
      <p className="income-subtitle">
        Choose the option that best describes your income source
      </p>

      <div className="income-grid">

        <div
          className="income-card"
          onClick={() => handleSelect("Salary")}
          style={{ border: selectedIncome === "Salary" ? "2px solid #1e3c72" : "" }}
        >
          <div className="income-icon">💼</div>
          <div className="income-name">Salary</div>
          <div className="income-desc">Fixed monthly income</div>
        </div>

        <div
          className="income-card"
          onClick={() => handleSelect("Business")}
          style={{ border: selectedIncome === "Business" ? "2px solid #1e3c72" : "" }}
        >
          <div className="income-icon">🏢</div>
          <div className="income-name">Business</div>
          <div className="income-desc">Income from business</div>
        </div>

        <div
          className="income-card"
          onClick={() => handleSelect("Student")}
          style={{ border: selectedIncome === "Student" ? "2px solid #1e3c72" : "" }}
        >
          <div className="income-icon">🎓</div>
          <div className="income-name">Student</div>
          <div className="income-desc">Allowance / Part-time</div>
        </div>

        <div
          className="income-card"
          onClick={() => handleSelect("No Income")}
          style={{ border: selectedIncome === "No Income" ? "2px solid #1e3c72" : "" }}
        >
          <div className="income-icon">📉</div>
          <div className="income-name">No Income</div>
          <div className="income-desc">Currently not earning</div>
        </div>

      </div>

      <button
        onClick={handleContinue}
        style={{
          padding: "12px 30px",
          fontSize: "16px",
          borderRadius: "8px",
          border: "none",
          background: "#ffffff",
          color: "#1e3c72",
          cursor: "pointer"
        }}
      >
        Continue
      </button>
    </div>
  );
}

export default IncomeCategory;
